from qgis.core import QgsProject
project = QgsProject.instance()
print('project name: ' + project.title())
sym_layer = project.mapLayersByName('符号样式表')[0]
sym_map = {}
for feat in sym_layer.getFeatures():
    stype = str(feat['symbol_type']).strip()
    sym_map[stype] = {'path': str(feat['svg_path']).strip()}
print('symbol types found: ' + str(len(sym_map)))
for k, v in sym_map.items():
    print('  ' + k + ' -> ' + v['path'])
